    "category": "endocrinology",
    "titleRu": "ИНСУЛИНОНЕЗАВИСИМЫЙ САХАРНЫЙ ДИАБЕТ",
    "titleEn": "NON-INSULIN-DEPENDENT DIABETES MELLITUS (CASE STUDY)",
    "patientRu": null,
