    "sourceFieldIdEn": "li_title__4688613130581",
    "category": "endocrinology",
    "titleRu": "ИНСУЛИНОНЕЗАВИСИМЫЙ САХАРНЫЙ ДИАБЕТ",
    "titleEn": "NON-INSULIN DEPENDENT DIABETES MELLITUS",
