    "category": "musculoskeletal",
    "titleRu": "СИСТЕМНАЯ КРАСНАЯ ВОЛЧАНКА",
    "titleEn": "SYSTEMIC LUPUS ERYTHEMATOSUS",
    "patientRu": null,
    "patientEn": "A 37-year-old patient",
